alter table public.timeline_daw_normalization_render_jobs add column if not exists artifact_byte_length bigint check(artifact_byte_length>=0);
create table if not exists public.timeline_daw_normalization_worker_runs(id text primary key,started_at timestamptz not null,finished_at timestamptz not null,worker_id text not null,claimed integer not null,completed integer not null,failed integer not null,elapsed_ms integer not null,next_wakeup text not null check(next_wakeup in('drained','continue','failed')),failure_messages jsonb not null default '[]'::jsonb);alter table public.timeline_daw_normalization_worker_runs enable row level security;
create or replace function public.claim_next_timeline_daw_normalization_render(p_worker text,p_lease_token text,p_lease_seconds integer default 120) returns setof public.timeline_daw_normalization_render_jobs language plpgsql security definer set search_path=public as $$ begin if current_user not in('service_role','postgres') then raise exception 'service role required'; end if;return query update public.timeline_daw_normalization_render_jobs j set state='rendering',lease_token=p_lease_token,lease_owner=p_worker,lease_expires_at=now()+make_interval(secs=>greatest(15,least(p_lease_seconds,300))),heartbeat_at=now(),attempt=j.attempt+1,updated_at=now() where j.id=(select x.id from public.timeline_daw_normalization_render_jobs x where not x.cancel_requested and x.artifact_checksum is null and (x.state in('queued','failed') or (x.state='rendering' and x.lease_expires_at<now())) order by x.created_at for update skip locked limit 1) returning j.*;end $$;revoke all on function public.claim_next_timeline_daw_normalization_render(text,text,integer) from public,anon,authenticated;grant execute on function public.claim_next_timeline_daw_normalization_render(text,text,integer) to service_role;